static int moving_average(int value)
{
    filter_sum -= filter_buffer[filter_index];

    filter_buffer[filter_index] = value;

    filter_sum += value;

    filter_index++;

    if (filter_index >= FILTER_SIZE)
    {
        filter_index = 0;
    }

    return filter_sum / FILTER_SIZE;
}


